#!/usr/bin/env python3
"""PreToolUse guard: block writes to Claude's file memory and redirect to brain.

Durable knowledge belongs in a brain document (captain rule, 2026-10-20).
Claude's memory directory is invisible to the rest of the fleet.
"""
import json
import re
import sys

MEMORY = re.compile(r"\.claude/projects/[^\s\"']*/memory(/|\b)")
WRITE_TOOLS = {"Write", "Edit", "MultiEdit", "NotebookEdit"}
REDIRECT = (
    "Blocked: Claude file memory is not allowed. It is invisible to the rest of the fleet. "
    "Durable knowledge goes in a brain document: `brain create \"<title>\" --description \"...\"` "
    "(or `brain remember`). Procedures go in a runbook (`runbooks`), run logs in status-kdv, "
    "defects in robots, work items in task."
)


def main() -> int:
    try:
        event = json.load(sys.stdin)
    except (json.JSONDecodeError, ValueError):
        return 0
    tool = event.get("tool_name", "")
    tool_input = event.get("tool_input", {}) or {}
    hit = False
    if tool in WRITE_TOOLS:
        target = tool_input.get("file_path") or tool_input.get("notebook_path") or ""
        hit = bool(MEMORY.search(target))
    elif tool == "Bash":
        hit = bool(MEMORY.search(tool_input.get("command", "") or ""))
    if not hit:
        return 0
    print(json.dumps({
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "deny",
            "permissionDecisionReason": REDIRECT,
        }
    }))
    return 0


if __name__ == "__main__":
    sys.exit(main())

