#!/usr/bin/env bun
/**
 * PostToolUse.dispatcher.hook.ts — unified PostToolUse dispatcher
 * (task-rf0a / decision-y3y). Replaces 14 individually-registered PostToolUse
 * hook entries across 11 matcher groups.
 *
 * OUTPUT CONTRACT (PostToolUse): a hook may inject context (stdout JSON) or
 * block via exit code 2 (its stderr is fed back to the model). The SYNC modules
 * here have DISJOINT matchers — for any single tool at most one sync module
 * emits: ContentScanner on WebFetch/WebSearch, PulseDesignSystem (exit-2) on
 * Edit|Write|MultiEdit, CompleteHandoff on Bash, the two Agent side-effect hooks
 * (no stdout). So the faithful reducer is verbatim passthrough of sync stdout +
 * exit-2 propagation — NOT re-interpretation (ContentScanner emits a non-standard
 * {hookSpecificOutput:"<string>"} shape that must reach CC byte-for-byte).
 *
 * ASYNC modules (IsaLifter, PersonLifter, ToolActivityTracker, ContentScanner-on-
 * all, ParlayTurnMirror, SessionActivityLog) are side-effects fired detached.
 *
 * Note (parity, not a new bug): ContentScanner is registered BOTH sync on the web
 * tools AND async on '' (all tools) in the prior settings, so it runs twice on a
 * WebFetch/WebSearch. Reproduced here for exact parity.
 */

import { homedir } from 'os';
import { join } from 'path';
import {
  runModules, loadDropIns, readRawStdin, toolNameFromRaw, type Module, type SpawnResult,
} from '../lib/dispatcher.ts';

const H = join(homedir(), '.claude', 'hooks');

// Declaration order mirrors the prior settings.universal.json PostToolUse groups.
const MODULES: Module[] = [
  { name: 'ContentScanner:web',    path: join(H, 'events/post-tool/ContentScanner.hook.ts'),    matcher: 'WebFetch',  timeoutMs: 5_000 },
  { name: 'ContentScanner:search', path: join(H, 'events/post-tool/ContentScanner.hook.ts'),    matcher: 'WebSearch', timeoutMs: 5_000 },
  { name: 'AgentInvocation',       path: join(H, 'events/pre-tool/AgentInvocation.hook.ts'),   matcher: 'Agent',     timeoutMs: 5_000 },
  { name: 'AgentUnsubscribeProxy', path: join(H, 'events/post-tool/AgentUnsubscribeProxy.hook.ts'), matcher: 'Agent', timeoutMs: 6_000 },
  { name: 'IsaLifter',             path: join(H, 'events/post-tool/IsaLifter.hook.ts'),         matcher: 'Write|Edit', timeoutMs: 5_000, async: true },
  { name: 'PersonLifter',          path: join(H, 'events/post-tool/PersonLifter.hook.ts'),      matcher: 'Write|Edit', timeoutMs: 5_000, async: true },
  { name: 'ToolActivityTracker',   path: join(H, 'events/post-tool/ToolActivityTracker.hook.ts'), matcher: '',        timeoutMs: 5_000, async: true },
  { name: 'ContentScanner:all',    path: join(H, 'events/post-tool/ContentScanner.hook.ts'),    matcher: '',          timeoutMs: 5_000, async: true },
  { name: 'PulseDesignSystem',     path: join(H, 'events/post-tool/PulseDesignSystem.hook.ts'), matcher: 'Edit|Write|MultiEdit', timeoutMs: 15_000 },
  // NEW (task-61x): 250-line source-file guard. Async side-effect — mints a
  // type-linelimit refactor obligation (ObligationGuard blocks/discharges at Stop);
  // never emits stdout or blocks here. FLAG-gated OFF (line-limit-guard.enabled in
  // FLAGS.json) so it exits 0 immediately until deliberately activated.
  { name: 'LineLimitGuard',        path: join(H, 'events/post-tool/LineLimitGuard.hook.ts'),    matcher: 'Edit|Write|MultiEdit', timeoutMs: 8_000, async: true },
  { name: 'ParlayTurnMirror',      path: join(H, 'events/stop/ParlayTurnMirror.hook.ts'),  matcher: '*',         timeoutMs: 8_000, async: true },
  { name: 'SessionActivityLog',    path: join(H, 'events/post-tool/SessionActivityLog.hook.ts'), matcher: 'Edit|MultiEdit|Write|NotebookEdit|Bash|Task', timeoutMs: 10_000, async: true },
  { name: 'CompleteHandoff',       path: join(H, 'events/post-tool/CompleteHandoff.hook.ts'),   matcher: 'Bash',      timeoutMs: 15_000 },
  // NEW (task-qy2q): non-blocking orchestration guard — nudges an agent to
  // scope-and-delegate when it deep-reads another agent's repo. Sync so its
  // additionalContext reaches the model; disjoint output from CompleteHandoff
  // in practice (that only speaks on an actual handoff-completing Bash).
  { name: 'OrchestrationGuard',    path: join(H, 'events/post-tool/OrchestrationGuard.hook.ts'), matcher: 'Read|Grep|Glob|Bash', timeoutMs: 8_000 },
  // NEW (task-rgvb): firstmate delegation-discipline guard — nudges the mayor to
  // DELEGATE investigation (launch a background agent) instead of doing it inline.
  // Gated to firstmate-home sessions (.fm-isolated-home marker); fleet-state reads exempt.
