  { name: 'DelegationDiscipline',  path: join(H, 'events/post-tool/DelegationDiscipline.hook.ts'), matcher: 'Read|Grep|Glob|Bash', timeoutMs: 8_000 },
];

export interface PostToolReduction {
  exit2: boolean;   // a sync module blocked via exit 2 (stderr already forwarded live)
  stdout: string;   // verbatim sync stdout to forward (at most one module in practice)
}

/**
 * Reducer (pure, testable). Exit-2 propagates a block (the module's stderr is
 * streamed live by spawnModule, so nothing to re-emit). Otherwise forward sync
 * modules' stdout verbatim, in declaration order (results are index-preserved;
 * sync modules run concurrently), so CC processes each control message exactly
 * as it would have from the individual hook.
 */
export function reducePostToolUse(results: SpawnResult[]): PostToolReduction {
  const exit2 = results.some((r) => r.exitCode === 2);
  const stdout = results.map((r) => r.stdout.trim()).filter((s) => s.length > 0).join('\n');
  return { exit2, stdout };
}

async function main(): Promise<void> {
  const raw = await readRawStdin();
  const toolName = toolNameFromRaw(raw);
  const results = await runModules([...MODULES, ...loadDropIns('PostToolUse')], raw, toolName);

  const { exit2, stdout } = reducePostToolUse(results);
  if (stdout) process.stdout.write(stdout + '\n');
  process.exit(exit2 ? 2 : 0);
}

if (import.meta.main) {
  main().catch(() => process.exit(0));
}

