 * ACTION: sync additionalContext nudging the model to run the read-only
 *   classification (runbooks-u3q), close only CLOSE-SAFE panes (runbooks-0ha)
 *   via bin/fm-teardown.sh, and never force, discard, kill, or hand-prune a slot.
 *   Non-blocking: never emits decision:block or exit 2.
 */

const FIRSTMATE_HOME = '/Users/trilliumsmith/fm_home/firstmate';
const TRIGGER = 'worktrees are in use, dirty, or not provably';

const CONTEXT = `Treehouse worktree pool is full (every slot in use, dirty, or not provably this clone). Start the worktree-closing triage loop now, without waiting for the captain:
1. Run the read-only classification in runbooks-u3q (\`runbooks show runbooks-u3q\`) over the worktree panes. Label each WORKING / WAITING-EXTERNAL / WAITING-ON-FIRSTMATE / STALE-LANDED / STALE-UNLANDED / UNOWNED. Change nothing in this step.
2. Close only CLOSE-SAFE panes per runbooks-0ha (\`runbooks show runbooks-0ha\`): clean, landed or already done, no unpushed commits, idle over 1 hour. Use bin/fm-teardown.sh for each. Never use --force.
3. For idle REVIEW or KEEP panes over 1 hour, use bin/fm-control.sh <id> exit and file a staleness bead. Never kill processes.
4. Never return, remove, or prune a worktree slot by hand, never discard unlanded work, and leave anything you cannot prove landed for the captain.
5. Re-run the spawn that hit the full pool only if a slot was freed. Log the classification and actions as a comment on status-kdv.`;

async function main(): Promise<void> {
  const stdin = await Bun.stdin.text();
  if (!stdin.trim()) return;
  const input = JSON.parse(stdin);

  const fmHome = process.env.FM_HOME ?? '';
  if (fmHome && fmHome !== FIRSTMATE_HOME) return;

  // Match the tool RESULT only, never the command text.
  const response = JSON.stringify(input.tool_response ?? '');
  if (!response.includes(TRIGGER)) return;

  const out = {
    hookSpecificOutput: { hookEventName: 'PostToolUse', additionalContext: CONTEXT },
  };
  process.stdout.write(JSON.stringify(out) + '\n');
}

if (import.meta.main) {
  main().catch(() => process.exit(0));
}
